// canvas: shared function declarations; initialized by bolxiv.js in the documented order.
function blockReadOnlyEvent(event){event.preventDefault();event.stopImmediatePropagation()}

function readOnlyTarget(target){return target instanceof Element&&!!target.closest(readOnlyEditTargets)}

// LAN HTTP origins lack randomUUID, but still support getRandomValues.
function createObjectId(){
 if(typeof crypto.randomUUID==='function')return crypto.randomUUID();
 const bytes=crypto.getRandomValues(new Uint8Array(16));
 bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;
 const hex=Array.from(bytes,byte=>byte.toString(16).padStart(2,'0')).join('');
 return hex.slice(0,8)+'-'+hex.slice(8,12)+'-'+hex.slice(12,16)+'-'+hex.slice(16,20)+'-'+hex.slice(20);
}

function selectPlacementTool(type){tool=type;activeIcon=null;document.querySelectorAll('.tool').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.icon-choice').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});document.querySelectorAll('.tool[data-tool]').forEach(button=>{const active=button.dataset.tool===type;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))})}

function selectPlacementIcon(icon,refresh=true){activeIcon=icon;tool='icon';document.querySelectorAll('.tool').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.icon-choice').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.icon-choice').forEach(button=>{const active=button.title===icon.name;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))})}

function renderIconGrid(group,gridId){group=group||$('#iconGroup').value;let grid=$('#'+(gridId||'iconGrid'));grid.innerHTML='';for(let [name,folder,fileName,badge=''] of iconFiles[group]){let src=iconPath(fileName,folder),imageSrc=embeddedPngs[src]||src,b=document.createElement('button');b.className='icon-choice';b.title=name;b.draggable=true;b.innerHTML=`<img src="${imageSrc}" alt="${name}">${badge?`<span class="role-badge">${badge}</span>`:''}`;let icon={name,src,badge};b.onclick=()=>{selectPlacementIcon(icon);};b.ondragstart=e=>{selectPlacementIcon(icon,false);e.dataTransfer.setData('application/x-tactica',JSON.stringify({type:'icon',...icon}));e.dataTransfer.effectAllowed='copy'};grid.appendChild(b)}}

