function renderTargetPurpleIcon(){const grid=document.getElementById('aoeTools');if(!grid)return;grid.querySelector('[data-aoe-icon="target-purple"]')?.remove();const icon={name:'ターゲット紫',src:'assets/aoe/target-purple.svg',badge:''},button=document.createElement('button');button.className='icon-choice';button.dataset.aoeIcon='target-purple';button.title=icon.name;button.setAttribute('aria-label',icon.name);button.draggable=true;button.innerHTML='<img src="'+embeddedPngs[icon.src]+'" alt="'+icon.name+'">';button.onclick=()=>{selectPlacementIcon(icon);};button.ondragstart=e=>{selectPlacementIcon(icon,false);e.dataTransfer.setData('application/x-tactica',JSON.stringify({type:'icon',...icon}));e.dataTransfer.effectAllowed='copy'};grid.appendChild(button)}

