 const note=document.createElement('p');note.className='hint locked-selection-hint';note.textContent=(items.length===1?'編集不可':count+'個が編集不可')+'：キャンバス上では移動・サイズ変更できません。上の鍵ボタンで解除できます。';const kind=el.querySelector('.property-kind-row');if(kind)kind.after(note);else{note.textContent=note.textContent.replace('上の鍵ボタン','オブジェクトリストの鍵ボタン');el.prepend(note)}
