function snappedObjectMove(items,starts,dx,dy,width,height,minX,maxX,minY,maxY){let moving=new Map(starts.map(item=>[item.id,item])),bestX=Infinity,bestY=Infinity,snapX=dx,snapY=dy;for(let item of items){let start=moving.get(item.id);if(!start||!item.bounds||item.visible===false)continue;let shiftX=dx-(item.x-start.x)/100*width,shiftY=dy-(item.y-start.y)/100*height;for(let edge of [item.bounds.left,(item.bounds.left+item.bounds.right)/2,item.bounds.right]){let correction=width/2-(edge+shiftX),distance=Math.abs(correction),candidate=dx+correction;if(distance<=3&&distance<bestX&&candidate>=minX&&candidate<=maxX){bestX=distance;snapX=candidate}}for(let edge of [item.bounds.top,(item.bounds.top+item.bounds.bottom)/2,item.bounds.bottom]){let correction=height/2-(edge+shiftY),distance=Math.abs(correction),candidate=dy+correction;if(distance<=3&&distance<bestY&&candidate>=minY&&candidate<=maxY){bestY=distance;snapY=candidate}}for(let other of items){if(moving.has(other.id)||other.visible===false||!other.bounds)continue;for(let edge of ['left','right'])for(let target of ['left','right']){let correction=other.bounds[target]-(item.bounds[edge]+shiftX),distance=Math.abs(correction),candidate=dx+correction;if(distance<=3&&distance<bestX&&candidate>=minX&&candidate<=maxX){bestX=distance;snapX=candidate}}for(let edge of ['top','bottom'])for(let target of ['top','bottom']){let correction=other.bounds[target]-(item.bounds[edge]+shiftY),distance=Math.abs(correction),candidate=dy+correction;if(distance<=3&&distance<bestY&&candidate>=minY&&candidate<=maxY){bestY=distance;snapY=candidate}}}}return {dx:snapX,dy:snapY}}

function placementAlignment(payload,clientX,clientY,disabled=false){const rect=stage.getBoundingClientRect(),width=stage.clientWidth,height=stage.clientHeight,x=(clientX-rect.left)/rect.width*100,y=(clientY-rect.top)/rect.height*100;if(disabled||!width||!height)return {x,y,guides:[]};const item=createPlacementObject(payload,x,y),cx=x/100*width,cy=y/100*height;item.id='placement-preview';item.bounds={left:cx-item.width/2,right:cx+item.width/2,top:cy-item.height/2,bottom:cy+item.height/2};const items=[...alignmentSnapshot(),item],snap=snappedObjectMove(items,[item],0,0,width,height,-Infinity,Infinity,-Infinity,Infinity);item.x+=snap.dx/width*100;item.y+=snap.dy/height*100;item.bounds={left:item.bounds.left+snap.dx,right:item.bounds.right+snap.dx,top:item.bounds.top+snap.dy,bottom:item.bounds.bottom+snap.dy};return {x:item.x,y:item.y,guides:[...objectAlignmentGuides(items,[item.id]),...boardCenterGuides(items,[item.id],[],width,height).map(guide=>({...guide,centerLine:true}))]}}

