function paintKeyboardNudge(){
 keyboardNudgeFrame=null;const session=keyboardNudgeSession;
 if(!session||session.board!==data||session.page!==current())return;
 for(const item of session.items){const node=session.nodes.get(item.id);if(node){node.style.left=item.x+'%';node.style.top=item.y+'%';if(item.type==='targetcircle')refreshTargetCircleTriangle(item,node)}const box=session.boxes.get(item.id);if(box){box.style.left=item.x+'%';box.style.top=item.y+'%'}}
 const item=session.items.find(o=>o.id===selected);
 if(item&&selectedIds.length===1){for(const [axis,size] of [['X',session.width],['Y',session.height]]){const value=Math.round(item[axis.toLowerCase()]/100*size);for(const suffix of ['', 'Spin']){const input=document.getElementById('object'+axis+suffix);if(input)input.value=value}const label=document.getElementById('object'+axis+'Value');if(label)label.textContent=value}}
}

